    out = [row[:] for row in grid]
    height, width = len(grid), len(grid[0])
    sequences = []
    source_rows = set()

    for r, row in enumerate(grid):
        c = 0
        while c < width:
            if row[c] == 0:
                c += 1
                continue
            start = c
            while c < width and row[c] != 0:
                c += 1
            if c - start >= 3:
                sequences.append(row[start:c])
                source_rows.add(r)

    sequence_for_color = {color: seq for seq in sequences for color in seq}
    for r, row in enumerate(grid):
        if r in source_rows:
            continue
        for c, color in enumerate(row):
            seq = sequence_for_color.get(color)
            if seq is None:
                continue
            anchor = seq.index(color)
            for i, value in enumerate(seq):
                target_c = c + i - anchor
                if 0 <= target_c < width:
                    out[r][target_c] = value
    return out
